/* ---------- sheets ---------- */
const sheet=document.getElementById('sheet'), sheetBg=document.getElementById('sheetBg'); let sheetOpener=null;
function showSheet(html,keep){ const was=sheet.classList.contains('on'), y=sheet.scrollTop, g=was&&keep?focusSig(document.activeElement):null;
  document.getElementById('toast').classList.remove('show','live'); if(!was) sheetOpener=document.activeElement;
  sheet.innerHTML='<div class="handle"></div>'+html+`<div class="row" style="margin-top:12px"><button type="button" class="btn ghost sm" data-act="close">${L('Close','Fermer')}</button></div>`;
  sheet.classList.add('on'); sheetBg.classList.add('on'); sheet.setAttribute('aria-hidden','false'); document.documentElement.classList.add('locked');
  sheet.scrollTop=was&&keep?y:0; if(!refocus(sheet,g)) try{ sheet.focus({preventScroll:true}); }catch(e){} }
function closeSheet(){ if(!sheet.classList.contains('on')) return; sheet.classList.remove('on'); sheetBg.classList.remove('on'); sheet.setAttribute('aria-hidden','true'); document.documentElement.classList.remove('locked'); const o=sheetOpener, g=focusSig(o); sheetOpener=null;
  if(UI.dirty){ UI.dirty=false; render(true); }                                                    /* a conclusion was written: the screen behind shows it */
  if(o&&document.body.contains(o)){ try{ o.focus({preventScroll:true}); }catch(e){} } else refocus(document,g); }

const COL=()=>L(': ','\u00a0: ');
const cap=s=>s.charAt(0).toUpperCase()+s.slice(1);
function dShort(k){ if(!k) return ''; const [y,m,d]=String(k).slice(0,10).split('-').map(Number); return new Date(y,m-1,d).toLocaleDateString(LOC(),{day:'numeric',month:'short',year:'numeric'}); }
const PN={today:1,week:7,month:30};
const perName=per=>{ const r=NPERS.find(x=>x[0]===per); return L(r[1],r[2]); };
/* the meals of one period, for the sheets that list what is behind a number */
function mealsIn(I,per){ const out=[], T=today(); for(let i=PN[per]-1;i>=0;i--){ const d=I.D[kAdd(T,-i)]; if(d) out.push(...d.meals); } return out; }

/* ---------- Nutrition: what is behind the histamine line ---------- */
function histamineSheet(){ const I=IX(), per=S.nper, rows={}; let mg=0;
  for(const m of mealsIn(I,per)) for(const it of m.e.items){ const f=food(it.key); if(!f||f.none||!f.h) continue; const r=rows[it.key]||(rows[it.key]={f,q:0}); r.q+=it.q; if(f.hist!=null) mg+=f.hist*it.q; }
  const list=Object.values(rows).sort((a,b)=>(b.f.hist||0)*b.q-(a.f.hist||0)*a.q);
  showSheet(`<h3 id="sheetTitle">${L('Histamine, estimated','Histamine, estimée')} · ${perName(per)}</h3>
  ${list.length?`<ul class="evs">${list.map(r=>`<li>${qtxt(r.q)}\u00a0×\u00a0${esc(fname(r.f))} · ${r.f.hist!=null?'≈\u00a0'+U(r.f.hist*r.q,'mg',r.f.hist*r.q<1?2:1):L('no figure','valeur non attribuée')}</li>`).join('')}</ul><p class="small">${L('Total with a figure','Total des valeurs attribuées')}${COL()}<b>≈\u00a0${U(mg,'mg',mg<1?2:1)}</b></p>`:`<p>${L('No histamine food reported in this period.','Aucun aliment à histamine noté pour cette période.')}</p>`}
  <p class="small muted">${L('How the estimate is made: the weight of a serving, times the average for its food type in a 2011 table from the European Food Safety Authority. The amount in your own piece can be many times more or less. It counts how much histamine food you reported. It is not a measurement.','Comment l’estimation est faite\u00a0: le poids d’une portion, multiplié par la moyenne de son type d’aliment dans un tableau de 2011 de l’Autorité européenne de sécurité des aliments. La quantité dans ton propre morceau peut être plusieurs fois plus grande ou plus petite. Ça compte combien d’aliments à histamine tu as notés. Ce n’est pas une mesure.')}</p><p class="mine">${MINE()}</p>`); }
const NPERS=[['today','Today','Aujourd’hui'],['week','Week','Semaine'],['month','Month','Mois']];
/* the order, names, units and decimals of The Patch's chart */
const TN=[['prot','g','Protein','Protéines',0],['fib','g','Fibre','Fibres',0],['fe','mg','Iron','Fer',1],['mg','mg','Magnesium','Magnésium',0],['k','mg','Potassium','Potassium',0],['b1','mg','Thiamine (B1)','Thiamine (B1)',2],['b2','mg','Riboflavin (B2)','Riboflavine (B2)',1],['b3','mg','Niacin (B3)','Niacine (B3)',0],['b6','mg','Vitamin B6','Vitamine B6',1],['b12','mcg','B12','B12',1],['fol','mcg','Folate','Folate',0],['zn','mg','Zinc','Zinc',1],['se','mcg','Selenium','Sélénium',0],['cu','mg','Copper','Cuivre',1],['ca','mg','Calcium','Calcium',0],['c','mg','Vitamin C','Vitamine C',0],['e','IU','Vitamin E','Vitamine E',0],['d','IU','Vitamin D','Vitamine D',0],['va','mcg','Vitamin A','Vitamine A',0],['mn','mg','Manganese','Manganèse',1],['vk','mcg','Vitamin K','Vitamine K',0]];
const AGES=[['a1','18–30'],['a2','31–50'],['a3','51–70'],['a4','71+']], LIFE=[['veg','Vegetarian','Végétarien'],['preg','Pregnant','Enceinte'],['bf','Breastfeeding','Allaitement']];
/* 0.5.2: the reference amounts come from shared/nutrition.js, the same rules as The Patch and the Food Trial Log, from the answers shared with
   them on this phone (sex, age, weight, and smoking, pregnancy, breastfeeding, vegetarian or vegan). The newer answers win, wherever they were
   given. The wrench doesn't ask the kind of day or drinking most days: they're kept as another app gave them. No weight: the protein RDA. */
const HIDE=['work','drink','minor'], PFIELDS=['sex','age','wt','work','life'];
const PO={line:['Reference shown for','Référence montrée pour'],aria:['Change what the reference is worked out from','Changer ce qui sert à établir la référence'],title:['What the reference is worked out from','Ce qui sert à établir la référence']};
function myProf(){ const p=S.p||{}, o={}; for(const f of PFIELDS) if(p[f]!=null) o[f]=f==='life'?(p.life.length?p.life.slice():['none']):p[f]; return o; }
function myRef(){ const p=S.p||{}, l=Array.isArray(p.life)?p.life:[], m=p.sex==='m', preg=l.includes('preg')&&!m;
  return NUTRI.needs({sex:p.sex, age:p.age, kg:p.wt, work:p.work, smoke:l.includes('smoke'), preg, bf:l.includes('bf')&&!m&&!preg, veg:l.includes('veg')||l.includes('vegan')}); }
function takeProf(np){ for(const f of PFIELDS) if(np[f]!=null) S.p[f]=Array.isArray(np[f])?np[f].slice():np[f]; }
function pullProf(){ const sh=NUTRI.shared(); if(!sh||sh.t<=(S.pt||0)) return false; takeProf(sh.p); S.pt=sh.t; S.pp=JSON.stringify(myProf()); return true; }
function pushProf(){ const me=myProf(); if(!Object.keys(me).length) return; const js=JSON.stringify(me); if(js===S.pp) return; S.pt=NUTRI.share(me); S.pp=js; }
function openProf(keep){ showSheet(NUTRI.sheetHTML(myProf(),S.lang==='fr',HIDE,PO),keep);
  sheet.querySelectorAll('[data-pw]').forEach(b=>{ b.onclick=()=>{ const id=b.dataset.pw, v=b.dataset.v; takeProf(NUTRI.pick(myProf(),id,v)); render(true); openProf(true);
    const f=sheet.querySelector(`[data-pw="${id}"][data-v="${v}"]`); if(f) try{ f.focus({preventScroll:true}); }catch(e){} }; }); }
const REFLINE=()=>L('Reference amounts come from Health Canada’s Dietary Reference Intakes and are shown for comparison only. The app doesn’t endorse them or advise on them. Health Canada has no connection with this app. This doesn’t replace a dietitian.','Les quantités de référence viennent des Apports nutritionnels de référence de Santé Canada et sont montrées pour comparaison seulement. L’app ne les endosse pas et ne donne pas de conseil à leur sujet. Santé Canada n’a aucun lien avec cette app. Ça ne remplace pas une diététiste.');
function listAmounts(){ const a=E.ZERO(); for(const k of S.list) E.addInto(a,E.amounts(food(k),S.amt[k]||1)); return a; }
const WHY={fall:['newest food before reported symptoms','l’aliment le plus récent avant des symptômes notés'],roll:['taken off the list again','retiré de la liste de nouveau'],react:['a reaction was reported when it was brought back','une réaction a été notée quand il a été ramené'],swap:['swapped out','échangé'],stop:['taken off in step 1','retiré à l’étape 1']};
function whyTxt(r){ const w=WHY[r.why]||WHY.stop; return L(w[0],w[1])+(r.times>1?L(` · ${r.times} times`,` · ${r.times} fois`):'')+(r.allergy?L(' · hives reported in its trial',' · urticaire notée pendant son essai'):''); }
function gutPresent(){ for(const k of GUTKEYS){ try{ if(localStorage.getItem(k)) return true; }catch(e){} } return false; }
function vNut(){ const I=IX(), per=S.nper, W=E.went(I,per), anyMeal=S.ev.some(e=>e.k==='meal'), fromList=!anyMeal&&S.list.length>0, has=fromList||W.days>0;
  const am=fromList?listAmounts():W.am, div=fromList?1:Math.max(1,W.days), ref=myRef(), tog=UI.tog||{};
  const capn=fromList?L('No meal reported yet. This is your list at its usual amounts, once a day.','Aucun repas noté pour l’instant. Voici ta liste à ses quantités habituelles, une fois par jour.')
    :per==='today'?L('Today, so far.','Aujourd’hui, jusqu’ici.')
    :W.days?L(`A day, on average: the ${W.days} day${W.days>1?'s':''} with a meal in the last ${PN[per]}.`,`Une journée, en moyenne\u00a0: ${W.days>1?`les ${W.days} jours`:'le jour'} avec un repas dans les ${PN[per]} derniers.`):'';
  /* portions that carry no numbers, and portions of label foods (a label doesn't list these vitamins and minerals) */
  let nn=0, nl=0; if(fromList){ for(const k of S.list){ const f=food(k); if(f.none) nn+=S.amt[k]||1; else if(!f.m) nl+=S.amt[k]||1; } } else for(const m of mealsIn(I,per)) for(const it of m.e.items){ const f=food(it.key); if(f.none) nn+=it.q; else if(!f.m) nl+=it.q; }
  let plus=false; const rows=TN.map(([k,u,en,fr,d])=>{ const v=(k==='prot'?am.prot:k==='fib'?am.fib:am.mic?am.mic[E.MICRO.indexOf(k)]:0)/div, r=ref[k], pc=Math.round(v/r*100);
    if(am.x&&am.x[k]>0) plus=true;
    return `<tr><th scope="row">${L(en,fr)}, ${u==='IU'?L('IU','UI'):u}</th><td>${has?num(v,d)+(am.x&&am.x[k]>0?'<span aria-hidden="true">+</span><span class="vh">'+L(' or more',' ou plus')+'</span>':''):'–'}</td><td>${num(r,d)}</td><td>${has?L(pc+'%',pc+'\u00a0%'):'–'}</td></tr>`; }).join('');
  const listTxt=S.list.map(k=>esc(fname(food(k)))+((S.amt[k]||1)!==1?'\u00a0×\u00a0'+qtxt(S.amt[k]):'')).join(', ');
  let imp;
  if(S.imp){ const o=S.imp.out, a=S.imp.aside, C=o.length?E.common(o.map(r=>r.key),S.list,food):null;
    imp=`<p class="small muted" style="margin:0 0 8px">${L('Brought in on','Importé le')} ${esc(dShort(S.imp.at))}${S.imp.from==='file'?L(', from its backup file',', à partir de son fichier de sauvegarde')+(S.imp.saved?L(' of ',' du ')+esc(dShort(S.imp.saved)):''):L(', from this phone',', à partir de ce téléphone')}.</p>
    <h3>${L('Rejected','Rejetés')} · ${o.length}</h3>${o.length?`<ul class="evs">${o.map(r=>`<li><button type="button" class="lnk" data-act="foodrd" data-v="${esc(r.key)}">${esc(fname(food(r.key)))}</button><br><span class="small muted">${esc(dShort(r.d))} · ${whyTxt(r)}</span></li>`).join('')}</ul>`:`<p class="small muted">${L('No food failed a trial there.','Aucun aliment n’a échoué à un essai là-bas.')}</p>`}
    ${a.length?`<h3 style="margin-top:12px">${L('Set aside','Mis de côté')} · ${a.length}</h3><p class="small">${a.map(r=>esc(fname(food(r.key)))+' ('+whyTxt(r)+')').join(', ')}</p>`:''}
    ${C&&(C.rows.length||C.typ.length)?`<h3 style="margin-top:12px">${L('In common','En commun')}</h3>${C.rows.length?`<ul class="evs">${C.rows.map(r=>`<li>${L(BKN[r.b][0],BKN[r.b][1])}${COL()}${L(`${r.o} of the ${r.on} rejected · ${r.l} of the ${r.ln} on your list`,`${r.o} des ${r.on} rejetés · ${r.l} des ${r.ln} sur ta liste`)}</li>`).join('')}</ul>`:''}
      ${C.typ.length?`<table class="cov"><thead><tr><th scope="col" style="text-align:left">${L('One serving of the middle food','Une portion de l’aliment du milieu')}</th><th scope="col">${L('Rejected','Rejetés')}</th><th scope="col">${L('My list','Ma liste')}</th></tr></thead><tbody>${C.typ.map(t=>`<tr><th scope="row">${L(BARN[t.k][0],BARN[t.k][1])}, g</th><td>${num(t.o)}</td><td>${num(t.l)}</td></tr>`).join('')}</tbody></table><p class="small muted" style="margin:4px 0 0">${L('The middle food: half the foods hold more of it, half hold less.','L’aliment du milieu\u00a0: la moitié des aliments en contiennent plus, l’autre moitié moins.')}</p>`:''}
      <p class="mine">${L('Counts only.','Des données seulement.')} ${MINE()}</p>`:''}
    <div class="row" style="margin-top:10px">${gutPresent()?`<button type="button" class="btn ghost sm" data-act="impread">${L('Read it again','Le relire')}</button>`:''}<button type="button" class="btn ghost sm" data-act="impfile">${L('Choose a backup file','Choisir un fichier de sauvegarde')}</button></div>
    <button type="button" class="lnk" data-act="impdrop">${L('Remove what was brought in','Retirer ce qui a été importé')}</button>`; }
  else imp=`<p class="small">${L('Bring in your list, the foods it rejected, and what those have in common. The Food Trial Log itself isn’t changed.','Importe ta liste, les aliments qu’il a rejetés, et ce qu’ils ont en commun. Le Food Trial Log lui-même n’est pas modifié.')}</p>
    <div class="row">${gutPresent()?`<button type="button" class="btn sm" data-act="impread">${L('Read it from this phone','Le lire sur ce téléphone')}</button>`:''}<button type="button" class="btn ghost sm" data-act="impfile">${L('Choose its backup file','Choisir son fichier de sauvegarde')}</button></div>
    <p class="small muted" style="margin:10px 0 0">${L('The file comes from the Food Trial Log: Menu → Back up my data → Download a file. On an iPhone, an installed app doesn’t see another app’s data, so the file is the way.','Le fichier vient du Food Trial Log\u00a0: Menu → Sauvegarder mes données → Télécharger un fichier. Sur un iPhone, une app installée ne voit pas les données d’une autre app, alors il faut passer par le fichier.')}</p>`;
  return `<div class="gtabs seg toptabs" role="group" aria-label="${L('Period','Période')}">${NPERS.map(([k,en,fr])=>`<button type="button" data-act="nper" data-v="${k}" aria-pressed="${per===k}">${L(en,fr)}</button>`).join('')}</div>
  <div class="card">${capn?`<p class="small muted" style="margin:0 0 10px;text-align:center">${capn}</p>`:''}${ringHTML(am,div)}${keyHTML(am,div,has)}${has?`<p class="small muted" style="margin:8px 0 0;text-align:center">${L('Energy','Énergie')}${COL()}${U(am.kcal/div,'kcal',0)}</p>`:''}<p class="mine">${MINE()}</p></div>
  ${!fromList&&W.meals?`<div class="card" id="compCard"><p class="small muted" style="margin:0;text-align:center">${per==='today'?L('Today, in total.','Aujourd’hui, au total.'):L(`The last ${PN[per]} days, in total.`,`Les ${PN[per]} derniers jours, au total.`)}</p>${compHomeHTML(W.am)}<p class="mine">${MINE()}</p></div>`:''}
  <div class="card">${NUTRI.lineHTML(myProf(),S.lang==='fr',HIDE,PO)}<table class="cov" id="cov"><thead><tr><th scope="col" style="text-align:left">${L('In a day','Dans une journée')}</th><th scope="col">${L('You','Toi')}</th><th scope="col"><span aria-hidden="true">${L('Ref.','Réf.')}</span><span class="vh">${L('Reference','Référence')}</span></th><th scope="col"><span class="vh">${L('Share of the reference','Part de la référence')}</span><span aria-hidden="true">%</span></th></tr></thead><tbody>${rows}</tbody></table>
    ${nn?`<p class="small muted">${L(`${qtxt(nn)} portion${nn>1?'s':''} of a food with no numbers ${nn>1?'are':'is'} not in these amounts.`,`${qtxt(nn)} portion${nn>1?'s':''} d’un aliment sans valeurs attribuées ${nn>1?'ne sont':'n’est'} pas dans ces quantités.`)}</p>`:''}
    ${nl?`<p class="small muted">${L(`${qtxt(nl)} portion${nl>1?'s':''} of a food added from its label count${nl>1?'':'s'} for protein and fibre only: a label doesn’t list these vitamins and minerals.`,`${qtxt(nl)} portion${nl>1?'s':''} d’un aliment ajouté selon son étiquette ${nl>1?'comptent':'compte'} pour les protéines et les fibres seulement\u00a0: une étiquette n’indique pas ces vitamines et minéraux.`)}</p>`:''}
    ${plus?`<p class="small muted">${L('+ You reported a pill or a food with no figure for this one, so the amount is that or more.','+ Tu as noté une pilule ou un aliment sans valeur attribuée pour celui-ci, alors la quantité est celle-là ou plus.')}</p>`:''}
    <p class="small muted">${REFLINE()}</p></div>
  <div class="card"><div class="eyebrow">${L('My list','Ma liste')} · ${S.list.length}</div>${S.list.length?`<p class="small">${listTxt}</p>`:`<p class="small muted">${L('The foods you eat as a rule. It starts empty: pick them, or bring them from the Food Trial Log.','Les aliments que tu manges d’habitude. Elle commence vide\u00a0: choisis-les, ou importe-les du Food Trial Log.')}</p>`}<button type="button" class="btn ghost sm" data-act="list">${S.list.length?L('Change my list','Modifier ma liste'):L('Pick my foods','Choisir mes aliments')}</button></div>
  <div class="card"><div class="eyebrow">${L('From the Food Trial Log','Du Food Trial Log')}</div>${imp}<input type="file" id="impFile" accept="application/json,.json" class="vh" tabindex="-1" aria-hidden="true"></div>`; }

/* ---------- the import ---------- */
/* food numbers the Food Trial Log retired in its version 1.2.0, and the foods that replaced them (its own table) */
const MERGED={842:[920001,1.75],854:[920001,1],501869:[920001,1],501872:[920001,1],6146:[920002,1.5],133:[130,2],3183:[920004,1.25],3187:[920004,1]};
function mapGut(R){ const mOf=k=>k[0]==='f'?MERGED[+k.slice(1)]:null, mk=k=>{ const m=mOf(k); return m?'f'+m[0]:k; }, seen=new Set(), list=[];
  for(const x of R.list){ const m=mOf(x.key), key=mk(x.key), q=m?Math.min(8,Math.max(0.5,Math.round(x.q*m[1]*2)/2)):x.q; if(!seen.has(key)){ seen.add(key); list.push({key,q}); } }
  const ded=rows=>{ const s=new Set(); return rows.map(r=>Object.assign({},r,{key:mk(r.key)})).filter(r=>!seen.has(r.key)&&!s.has(r.key)&&s.add(r.key)); };
  return Object.assign({},R,{list,out:ded(R.out),aside:ded(R.aside),fine:[...new Set(R.fine.map(mk))]}); }
function impPreview(o,from,saved){ const R0=E.importGut(o); if(!R0){ toast(L('That isn’t a Food Trial Log save','Ce n’est pas une sauvegarde du Food Trial Log')); return; }
  const R=mapGut(R0); UI.imp={R,from,saved:saved||null};
  if(R.route!=='fast'){ showSheet(`<h3 id="sheetTitle">${L('Nothing to bring yet','Rien à importer pour l’instant')}</h3><p>${L('The Food Trial Log has a food list only on its fast route. This save isn’t on it.','Le Food Trial Log a une liste d’aliments seulement sur sa voie rapide. Cette sauvegarde n’y est pas.')}</p>`); return; }
  const cur=S.list.length, same=cur===R.list.length&&R.list.every(x=>S.list.includes(x.key));
  showSheet(`<h3 id="sheetTitle">${L('Bring these in?','Importer ceci?')}</h3><ul><li>${L('My list','Ma liste')}${COL()}${R.list.length} ${L(R.list.length===1?'food':'foods',R.list.length===1?'aliment':'aliments')}</li><li>${L('Rejected','Rejetés')}${COL()}${R.out.length}</li><li>${L('Set aside','Mis de côté')}${COL()}${R.aside.length}</li></ul>
  ${cur&&!same?`<p class="small"><b>${L(`This replaces the ${cur} food${cur>1?'s':''} on your list now.`,`Ça remplace ${cur>1?`les ${cur} aliments`:'l’aliment'} sur ta liste en ce moment.`)}</b></p>`:''}
  <p class="small muted">${L('The Food Trial Log isn’t changed, and its reports stay there.','Le Food Trial Log n’est pas modifié, et ses relevés restent là-bas.')}</p><button type="button" class="btn primary" data-act="impgo">${L('Bring them in','Importer')}</button>`); }
function impRead(){ const found=[]; for(const k of GUTKEYS){ try{ const r=localStorage.getItem(k); if(r){ const o=JSON.parse(r); if(o&&Array.isArray(o.ev)) found.push(o); } }catch(e){} }
  if(!found.length){ toast(L('No Food Trial Log data in this browser','Aucune donnée du Food Trial Log dans ce navigateur')); return; }
  const last=o=>o.ev.reduce((m,e)=>Math.max(m,+e.t||0),0); found.sort((a,b)=>last(b)-last(a)); impPreview(found[0],'phone'); }   /* English and French copies both there: the one used last */
function impFile(text){ let o; try{ o=JSON.parse(text); }catch(e){ o=null; }
  if(o&&o.app==='threshold-log'){ toast(L('That is a Threshold Log backup. Use Menu → Restore from a backup.','C’est une sauvegarde du Threshold Log. Va dans Menu → Restaurer à partir d’une sauvegarde.')); return; }
  if(o&&o.app==='food-trial-log'&&o.state) impPreview(o.state,'file',o.saved); else impPreview(o,'file'); }

/* ---------- Threshold: the data view. Pick an effect; read what was eaten for the meals or days it was reported for, beside all the others.
   Nothing is averaged and nothing is coloured: a range is the lowest and the highest amount, and "2 of 9" is how many held any. ---------- */
function rnum(x,w){ const d=w>=1?(Math.abs(w%1)>1e-9?1:0):(Math.round(w*100)%10?2:1); return (+x.toFixed(d)).toLocaleString(LOC(),{maximumFractionDigits:d}); }
const unitWord=(mode,n)=>mode==='day'?L(n===1?'day':'days',n===1?'journée':'journées'):L(n===1?'meal':'meals','repas');
const leftWhy=b=>b==='fib'?L('a fibre supplement with no figure, or a food with no numbers','un supplément de fibres sans valeur attribuée, ou un aliment sans valeurs attribuées'):b==='hist'?L('a histamine food with no figure, or a food with no numbers','un aliment à histamine sans valeur attribuée, ou un aliment sans valeurs attribuées'):b==='cplx'||b==='sug'?L('carbs of a kind not listed, or a food with no numbers','des glucides de sorte non indiquée, ou un aliment sans valeurs attribuées'):L('a food with no numbers','un aliment sans valeurs attribuées');
