const isP=b=>BARN[b][2]==='p', pw=x=>x===1?'portion':'portions';
function stepRange(B,s){ const u=isP(B.b)?null:BARN[B.b][2], t=x=>rnum(x,B.w)+' '+(u||pw(x));
  return s.i<0?(u?U(0,u,0):L('none of it','aucune portion')):s.i===0?L('up to ','jusqu’à ')+t(s.hi):rnum(s.lo,B.w)+L(' to ',' à ')+t(s.hi); }
const selOf=()=>S.tsel||[];
