    for(let j=0;j<m;j++){ const cy=n===1?y0+4+jit(ids[0])*(DH-8):y0+3+(j+.5)*(DH-6)/m; c+=`M${(+cx-r).toFixed(1)} ${cy.toFixed(1)}a${r} ${r} 0 1 0 ${2*r} 0a${r} ${r} 0 1 0 ${-2*r} 0`; }
