  const lane=(cl,d,p,n)=>d?`<path class="${cl}" data-n="${n}" data-p="${p.join(' ')}" d="${d}"/>`:'', nh=r.units.reduce((t,u)=>t+(u.fx.length?1:0),0); a=lane('dh',a,pa,nh); b=lane('dr',b,pb,r.units.length-nh);
